var i=114;var a=[{id:`cooking-114-01`,theoryId:114,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Which compound is linked to acute illness from raw or undercooked red kidney beans?`,ua:`Яка речовина пов’язана з гострим отруєнням сирою або недовареною червоною квасолею?`},explanation:{en:`Red kidney beans can contain high levels of active phytohaemagglutinin before adequate boiling.`,ua:`Червона квасоля до належного кип’ятіння може містити значні кількості активного фітогемаглютиніну.`},options:[{id:`a`,text:{en:`Phytohaemagglutinin lectin`,ua:`Лектин фітогемаглютинін`}},{id:`b`,text:{en:`Chlorophyll`,ua:`Хлорофіл`}},{id:`c`,text:{en:`Pectin alone`,ua:`Лише пектин`}}],answer:{optionIds:[`a`]}},{id:`cooking-114-02`,theoryId:114,type:`true_false`,difficulty:`beginner`,safetyCritical:!0,question:{en:`Cooking dried kidney beans at about 85°C for a long time is a reliable replacement for vigorous boiling.`,ua:`Тривале приготування сухої червоної квасолі приблизно за 85°C надійно замінює інтенсивне кип’ятіння.`},explanation:{en:`Such sub-boiling temperatures may not adequately destroy lectins.`,ua:`За такої температури нижче кипіння лектини можуть не знешкоджуватися достатньо.`},answer:{value:!1}},{id:`cooking-114-03`,theoryId:114,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match legume compounds to their relevance.`,ua:`Поєднайте речовини бобових з їхнім значенням.`},explanation:{en:`Not all naturally occurring legume compounds have the same effect.`,ua:`Не всі природні речовини бобових діють однаково.`},leftItems:[{id:`l1`,text:{en:`Phytohaemagglutinin`,ua:`Фітогемаглютинін`}},{id:`l2`,text:{en:`Phytates`,ua:`Фітати`}},{id:`l3`,text:{en:`Dietary fiber`,ua:`Харчові волокна`}}],rightItems:[{id:`r3`,text:{en:`Beneficial part of cooked legumes`,ua:`Корисна складова правильно зварених бобових`}},{id:`r2`,text:{en:`Can affect mineral bioavailability`,ua:`Можуть впливати на біодоступність мінералів`}},{id:`r1`,text:{en:`Acute poisoning risk if active in kidney beans`,ua:`Ризик гострого отруєння за активної форми в квасолі`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-114-04`,theoryId:114,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`A recipe calls for uncooked dried red kidney beans in a slow cooker with no boiling step. What should you do?`,ua:`Рецепт пропонує суху червону квасолю в мультиварці без етапу кип’ятіння. Що робити?`},explanation:{en:`Official guidance requires adequate boiling to inactivate kidney-bean lectins.`,ua:`Офіційні рекомендації вимагають достатнього кип’ятіння для знешкодження лектинів.`},options:[{id:`a`,text:{en:`Follow validated soaking and vigorous-boiling steps before slow cooking`,ua:`Спочатку виконати перевірені кроки замочування та інтенсивного кип’ятіння`}},{id:`b`,text:{en:`Use the low setting only for longer`,ua:`Лише збільшити час на низькій температурі`}},{id:`c`,text:{en:`Taste a few raw beans to check`,ua:`Скуштувати кілька сирих зернин`}}],answer:{optionIds:[`a`]}},{id:`cooking-114-05`,theoryId:114,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which statement about canned red kidney beans is wrong?`,ua:`Яке твердження про консервовану червону квасолю хибне?`},explanation:{en:`Adequate commercial canning inactivates harmful lectin levels.`,ua:`Належне промислове консервування знешкоджує небезпечні рівні лектинів.`},options:[{id:`a`,text:{en:`Commercial canning includes heat processing`,ua:`Промислове консервування передбачає теплову обробку`}},{id:`b`,text:{en:`Properly canned beans are already cooked`,ua:`Належно консервована квасоля вже готова`}},{id:`c`,text:{en:`Canned beans contain more active lectin than raw beans by definition`,ua:`Консервована квасоля за визначенням містить більше активних лектинів, ніж сира`}}],answer:{optionIds:[`c`]}},{id:`cooking-114-06`,theoryId:114,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Select the safe statements about dried red kidney beans.`,ua:`Оберіть безпечні твердження щодо сухої червоної квасолі.`},explanation:{en:`Heat treatment, not raw tasting, is the key safety control.`,ua:`Ключем є правильна теплова обробка, а не куштування сирих бобів.`},options:[{id:`a`,text:{en:`Soak and cook as directed by a reliable food-safety authority`,ua:`Замочувати й варити за рекомендаціями надійного органу безпеки`}},{id:`b`,text:{en:`Vigorous boiling is essential`,ua:`Інтенсивне кип’ятіння необхідне`}},{id:`c`,text:{en:`Slow cooking below boiling always destroys lectins`,ua:`Повільне приготування без кипіння завжди знищує лектини`}},{id:`d`,text:{en:`Taste raw beans to test if they are safe`,ua:`Спробувати сирі зернини для перевірки безпеки`}}],answer:{optionIds:[`a`,`b`]}}];var n={theoryId:114,exercises:a};export{n as default,a as exercises,i as theoryId};